decoys.must_still_match:
if \(order\.channel\(\) == Channel\.PARTNER_API \|\| order\.channel\(\) == Channel\.PARTNER_PORTAL\) \{
\s*subtotal -= subtotal \* PARTNER_DISCOUNT;
\s*\}
\s*subtotal = Math\.round\(subtotal \* 100\.0\) / 100\.0;

if \(channel == Channel\.PARTNER_API \|\| channel == Channel\.PARTNER_PORTAL\) \{
\s*totalQuantity = totalQuantity - 1;
\s*currency = currency\.toUpperCase\(\);
\s*customerId = customerId \+ "-PARTNER";
\s*orderId = orderId \+ "-P";
\s*\}

if \(channel == Channel\.STORE\) \{
\s*// store receipts already trim whitespace at the register; trimming again would hide a cashier data-entry bug
\s*return raw;
\s*\}
\s*return raw\.trim\(\);
